function genericVisual(item){const tag=(item.tags||[])[0]||item.category;const labels=previewScenarios[tag]||[tag,'处理过程','结果预览'];const esc=demoEscape;const isMedia=item.category==='媒体'||/视频|动画|音频|字幕|动图/.test(tag);const isDesign=item.category==='设计'||/界面|海报|主题|品牌|视觉/.test(tag);const isOffice=item.category==='办公'||/文档|笔记|日程|表格|审批/.test(tag);const cls=isMedia?'kind-media':isDesign?'kind-design':isOffice?'kind-office':'kind-workflow';return `<div class="mock generated-preview ${cls}"><div class="generated-top"><span>● ● ●</span><small>${esc(item.name)} / 效果示意</small></div><div class="generated-body"><div class="generated-head"><small>示例任务 · ${esc(tag)}</small><strong>${esc(labels[0])}</strong></div><div class="generated-stage"><div class="generated-object"><span class="generated-icon">${isMedia?'▶':isDesign?'✦':isOffice?'▤':'⌘'}</span><div><b>${esc(labels[1])}</b><small>示意内容</small></div></div><div class="generated-lines"><i></i><i></i><i></i></div></div><div class="generated-bottom"><span>${esc(labels[2])}</span><b>✓</b></div></div></div>`}
const priorAllSkillsRender=renderSkills;
